import type { Player } from "../data/mockPlayers";
import { ensureStringArray, toCanonicalAvailability } from "./matchProfile";

// Raw record returned by the suggested-players and specific-user endpoints
// (`/player/surveys/.../getchecklocation`). Shared by the Find Players
// directory and the visitor player profile so both render identically.
export type SuggestedPlayerRecord = {
  userId: number;
  email?: string;
  phone?: string;
  /** The API can text this player a hit request (they have a textable number). */
  can_receive_hit_request?: boolean;
  full_name?: string;
  profile_picture?: string;
  skillLevel?: string;
  availability?: string[] | string;
  playerLocations?: string[] | string;
  playerCourtLocations?: string[] | string;
  courts?: string[] | string;
  lookingFor?: string[] | string;
  gender?: string;
  about_me?: string;
  genderAdditionalText?: string;
  isLevelConfirmed?: boolean;
  verifiedLevelCount?: string | number;
  /** NTRP from the player's match results; null until they've played a rated match. */
  resultsNtrp?: number | string | null;
  /** Rated matches behind resultsNtrp; null when there is no results NTRP. */
  resultsMatchesPlayed?: number | string | null;
  is_favorite?: boolean;
  [key: string]: unknown;
};

/**
 * Where a player's shown level comes from, strongest first:
 *   "results"  their rated matches put them there
 *   "vouched"  enough other players vouched for the level they gave
 *              (the API counts only vouches for their current level)
 *   "self"     only what they told us in their match profile
 */
export type LevelSource = "results" | "vouched" | "self" | null;

export type DirectoryPlayer = Player & {
  raw: SuggestedPlayerRecord;
  levelSource: LevelSource;
  /** Rated matches behind a "results" level, else null. */
  resultsMatches: number | null;
};

/** Vouches the API needs before a level counts as vouched (VOUCHES_NEEDED in ttp-api). */
export const VOUCHES_NEEDED = 3;

/**
 * The few words that say how a level is known: "12 matches", "Vouched by 4" or
 * "Self-rated". Null when there is no level to explain.
 */
export const levelEvidenceLabel = (
  player: Pick<DirectoryPlayer, "levelSource" | "resultsMatches" | "verificationCount">,
): string | null => {
  if (player.levelSource === "results") {
    const count = player.resultsMatches;
    if (!count) return "From match results";
    return `${count} ${count === 1 ? "match" : "matches"}`;
  }
  if (player.levelSource === "vouched") return `Vouched by ${player.verificationCount}`;
  if (player.levelSource === "self") return "Self-rated";
  return null;
};

/** "3.5" for a half level, "3.75" for a quarter, as the ladder writes them. */
const formatNtrp = (value: number) =>
  Number.isInteger(value * 2) ? value.toFixed(1) : value.toFixed(2);

/** The results NTRP when it is a usable level, else null. */
export const resultsLevelOf = (record: Pick<SuggestedPlayerRecord, "resultsNtrp">): string | null => {
  const raw = record.resultsNtrp;
  if (raw === null || raw === undefined || raw === "") return null;
  const value = Number(raw);
  return Number.isFinite(value) && value > 0 && value <= 7 ? formatNtrp(value) : null;
};

/**
 * The level-filter option a level falls under: a 3.75 from results is a 3.5
 * player, so it counts under "3.5" rather than under no option at all.
 */
export const levelFilterBucket = (level: string | null | undefined): string | null => {
  const value = Number.parseFloat(String(level ?? ""));
  if (!Number.isFinite(value) || value <= 0) return null;
  return (Math.floor(value * 2) / 2).toFixed(1);
};

export const toInitials = (name: string): string => {
  const segments = name
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (segments.length === 0) {
    return "TP";
  }
  if (segments.length === 1) {
    return segments[0].slice(0, 2).toUpperCase();
  }
  return `${segments[0][0]}${segments[segments.length - 1][0]}`.toUpperCase();
};

// Bios people type to get past a required field. A single token is never a bio, and
// these turn up verbatim in the data.
const JUNK_BIO = /^(nil|null|none|na|n\/a|nada|test|testing|asdf|qwerty|abc|xyz|\.|-|\?)+$/i;

/**
 * Whether a bio is worth giving space to. Empty, single-token and filler answers all
 * collapse, so the card shows nothing instead of reserving a line for "Nil".
 */
export const isMeaningfulBio = (value: unknown): boolean => {
  if (typeof value !== "string") return false;
  const text = value.trim();
  if (text.length === 0) return false;
  if (JUNK_BIO.test(text.replace(/\s+/g, ""))) return false;
  return /\s/.test(text);
};

export const mapSuggestedPlayer = (record: SuggestedPlayerRecord): DirectoryPlayer => {
  const availability = ensureStringArray(record.availability, toCanonicalAvailability);
  const playerLocations = ensureStringArray(record.playerLocations);
  const courtLocations = ensureStringArray(record.playerCourtLocations ?? record.courts);
  const lookingFor = ensureStringArray(record.lookingFor);
  const location = playerLocations[0] ?? courtLocations[0] ?? "Location unavailable";
  const initialsSource = record.full_name ?? record.email ?? "TTP Player";
  const skillLabel = typeof record.skillLevel === "string" ? record.skillLevel.trim() : "";
  const levelMatch = skillLabel.match(/NTRP\s*([0-9.]+)/i);
  const selfLevel = levelMatch?.[1] ?? skillLabel;
  // Results first: a level their matches back up outranks the one they gave us.
  const resultsLevel = resultsLevelOf(record);
  const normalizedLevel = resultsLevel ?? (selfLevel || "Unknown");
  const verificationCount = Number.parseInt(String(record.verifiedLevelCount ?? "0"), 10) || 0;
  const levelSource: LevelSource = resultsLevel
    ? "results"
    : selfLevel
      ? record.isLevelConfirmed
        ? "vouched"
        : "self"
      : null;
  const resultsMatchCount = Number.parseInt(String(record.resultsMatchesPlayed ?? ""), 10);
  const resultsMatches = resultsLevel && resultsMatchCount > 0 ? resultsMatchCount : null;
  const normalizedGender = (() => {
    const rawGender = typeof record.gender === "string" ? record.gender.trim().toLowerCase() : "";
    if (rawGender === "male") return "Male" as const;
    if (rawGender === "female") return "Female" as const;
    return "Other" as const;
  })();
  const courts = courtLocations.length > 0 ? courtLocations : playerLocations;
  // No placeholder here — an absent bio stays absent so the view layer can collapse
  // the space rather than reserve it for a sentence nobody wrote.
  const bio = typeof record.about_me === "string" ? record.about_me.trim() : "";

  return {
    id: String(record.userId ?? initialsSource.toLowerCase()),
    name: record.full_name?.trim() || record.email || "TTP Player",
    initials: toInitials(initialsSource),
    profileImageUrl:
      typeof record.profile_picture === "string" ? record.profile_picture.trim() : "",
    location,
    distanceMiles: 0,
    gender: normalizedGender,
    level: normalizedLevel,
    levelSource,
    resultsMatches,
    availability,
    matchPreferences: lookingFor,
    bio,
    verified: Boolean(record.isLevelConfirmed),
    verificationCount,
    verificationSupporters: [],
    lastActive: "Active recently",
    matchFrequency: "Match frequency unavailable",
    rating: 0,
    favoriteCourt: courts[0] ?? location,
    lookingFor: lookingFor.join(", ") || "Not specified",
    localCourts: courts,
    hitTypes: lookingFor,
    matchesPlayed: undefined,
    reviewsCount: undefined,
    responseTime: undefined,
    memberSince: undefined,
    matchHistory: undefined,
    reviews: undefined,
    raw: record,
  };
};

/** The suggested-players list, from a bare array or the usual envelopes. */
export const extractSuggestedPlayers = (payload: unknown): SuggestedPlayerRecord[] => {
  if (Array.isArray(payload)) {
    return payload as SuggestedPlayerRecord[];
  }
  if (payload && typeof payload === "object") {
    const record = payload as Record<string, unknown>;
    if (Array.isArray(record.data)) {
      return record.data as SuggestedPlayerRecord[];
    }
    if (Array.isArray(record.players)) {
      return record.players as SuggestedPlayerRecord[];
    }
    if (Array.isArray(record.results)) {
      return record.results as SuggestedPlayerRecord[];
    }
  }
  return [];
};

// The specific-user endpoint may return the record bare or wrapped. Pull the
// first usable record out of the common envelope shapes.
export const extractSuggestedPlayer = (payload: unknown): SuggestedPlayerRecord | null => {
  if (!payload || typeof payload !== "object") {
    return null;
  }
  if (Array.isArray(payload)) {
    return (payload[0] as SuggestedPlayerRecord) ?? null;
  }
  const record = payload as Record<string, unknown>;
  const nestedKeys = ["data", "player", "user", "result", "profile"] as const;
  for (const key of nestedKeys) {
    const value = record[key];
    if (Array.isArray(value) && value.length > 0) {
      return value[0] as SuggestedPlayerRecord;
    }
    if (value && typeof value === "object") {
      return value as SuggestedPlayerRecord;
    }
  }
  // Bare record (has the identifying field).
  if ("userId" in record || "full_name" in record || "email" in record) {
    return record as SuggestedPlayerRecord;
  }
  return null;
};

export const mapPublicPlayerProfileRecord = (payload: unknown): SuggestedPlayerRecord | null => {
  if (!payload || typeof payload !== "object") {
    return null;
  }
  const container = payload as Record<string, unknown>;
  const source = (container.player && typeof container.player === "object"
    ? container.player
    : container) as Record<string, unknown>;

  if (!source || typeof source !== "object") {
    return null;
  }

  const userId = source.userId ?? source.user_id;
  if (userId === undefined || userId === null) {
    return null;
  }

  return {
    ...source,
    userId: Number(userId),
    full_name: typeof source.full_name === "string" ? source.full_name : undefined,
    profile_picture: typeof source.profile_picture === "string" ? source.profile_picture : undefined,
    skillLevel:
      typeof source.skillLevel === "string"
        ? source.skillLevel
        : typeof source.usta_rating === "string"
          ? source.usta_rating
          : undefined,
    about_me:
      typeof source.about_me === "string"
        ? source.about_me
        : typeof source.profile_about_me === "string"
          ? source.profile_about_me
          : undefined,
  } as SuggestedPlayerRecord;
};
